insert into powertrains (id,model_id,year,name,code,note,live,generation_id) values ('cxca','gti',2015,'2.0T TSI Gen 3','CXCA / CXCB / DKFA','2015–2021 · 6-speed manual, DQ250 6-speed DSG (to 2018) or DQ381 7-speed DSG (2019+)',true,'gti-mk7') on conflict (id,model_id,year) do update set name=excluded.name, code=excluded.code, note=excluded.note, live=excluded.live, generation_id=excluded.generation_id;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('water-pump-mk7','cxca','water-pump-mk7','Water pump & thermostat housing','Engine',null,array['water pump','thermostat','coolant leak','overheating']::text[],true,'6 hr–1 day',3.5) on conflict (id) do update set guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('water-pump-mk7',$j${"id": "water-pump-mk7", "title": "Water pump & thermostat housing", "fits": "2015–2021 VW GTI (Mk7 / Mk7.5) · 2.0T TSI Gen 3", "heroId": "waterpump-mk7", "alsoFits": "2015–18 Golf, Golf R, Alltrack · 2014–17 Jetta/Passat 1.8T · 2013–17 Beetle · 2017–18 Macan 2.0 (FCP's fitment list); 2019+ GTI is the same layout with later part revisions", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "6 hr to a full day", "timeRepeat": "4 hr", "difficulty": 3.5, "cost": "$150–300 pump + housing · $40 coolant", "risk": "Fuel pressure at the HPFP · intake manifold off · plastic coolant fittings · aluminium throttle-body screws", "why": "If you keep a Mk7 GTI long enough you will do this. The water pump and thermostat live in one plastic module on the front of the block, under the intake manifold, driven by a small belt off the balance shaft. The plastic warps with heat cycles and the module weeps at its joints, so the fix is the whole module, and getting to it means the intake manifold comes off. Book time is five hours; FCP says six to a day for a first-timer.", "note": "FCP Euro's Mk7 GTI procedure is the reference (video and write-up with fastener sizes and torques); DAP and independent shops confirm it as the car's most common failure."}, "heroCap": "Front of the block under the intake manifold: pump and thermostat housing as one module on five captive screws, a belt from the balance-shaft pulley, coolant lines clipped into the housing, and one connector underneath.", "lifespan": {"title": "When to expect it", "headline": ["As early as 25,000 miles; typically around 50,000; almost certainly by 100,000"], "earliest": "25k (FCP)", "detail": "Coolant weeps at the housing joints or the pump's weep hole. Watch for a slowly dropping level with no puddle, a sweet smell after a drive, white or pink crust on the front of the block under the manifold, a low-coolant light, or intermittent overheating. Pulley shaft play or a squeak at idle means the bearing is going too.", "factors": ["Heat cycles (short trips, hot climates)", "Age of the plastic", "Freeze-thaw winters"], "inspect": ["Flashlight down the front of the block below the manifold and dipstick at every oil change"], "confidence": {"level": "high", "n": 4, "note": "FCP, DAP and independent-shop write-ups agree on the failure and the mileage."}}, "should": {"yesIf": ["Coolant level dropping with no visible puddle", "Sweet smell or crust under the manifold on the passenger side", "Low-coolant warning", "Intermittent overheating or a slow-to-warm gauge", "Squeak from the pump at idle or play in the pulley"], "codes": ["P0128", "P2181"], "notes": ["Buy the complete module: pump with the thermostat housing (INA is the OE supplier; 06K 121 011 family, revision by year). Replacing just the housing on an old pump, or the pump on an old housing, is how people do this twice.", "Aluminium housings exist and solve the warping; they cost more and some owners report fit fussiness. A latest-revision plastic module installed clean is a fine repair.", "This job relieves fuel pressure at the high-pressure pump and removes the manifold. Read the whole procedure before you start; the order matters and the fuel step is not optional.", "The Gen 3 has no rubber valve cover gasket to disturb here; the manifold gasket is the one to replace."], "confidence": {"level": "high", "n": 3, "note": "FCP procedure with torques; part strategy from FCP, DAP and NGP."}}, "parts": [{"tier": "oem", "name": "Water pump + thermostat housing module (INA)", "pn": "06K 121 011 (revision by VIN)", "note": "Ships as two pieces; assemble with the five T30s", "price": "$150–300", "links": []}, {"tier": "oe", "name": "Intake manifold gasket", "pn": "06K 129 717 (confirm)", "note": "Manifold's off", "price": "$15", "links": []}, {"tier": "oe", "name": "Coolant, G13 concentrate 1 gal + distilled water", "pn": "G 013 A8J 1G", "note": "", "price": "$30", "links": []}, {"tier": "oe", "name": "Belly-pan clips, any coolant line clip that breaks", "pn": "—", "note": "Order a few", "price": "$10", "links": []}], "aftermarket": [{"name": "INA module (OE supplier)", "note": "What the dealer fits, in the maker's box. Latest revision.", "price": "$150–250", "signal": "OE supplier", "links": [{"store": "FCP Euro procedure", "url": "https://www.fcpeuro.com/blog/how-to-replace-water-pump-thermostat-housing-mk7-vw-gti-beetle-jetta-macan"}]}, {"name": "Aluminium thermostat housing kits (various)", "note": "Metal housing on the pump. Solves warping; check fit reports for your year.", "price": "$250–400", "signal": "Metal housing", "links": []}], "tools": [{"name": "T20, T25, T30 (a stubby T30 for the belt cover), 7mm and 10mm and 13mm sockets, 17mm wrench (fuel line), 24mm socket (turn the crank), M10 triple-square, 32mm oil filter cap socket"}, {"name": "Hook picks (coolant line clips, connectors), flat-band hose-clamp pliers, a mirror and a light, magnetic pickup"}, {"name": "Torque wrench 2–20 Nm; drain pans; safety glasses"}, {"name": "Vacuum coolant fill tool (strongly recommended)"}], "before": ["Engine cold; the fuel system holds pressure and the coolant scalds.", "Safety glasses for the fuel step. Rag around the fitting.", "Photograph every connector and clip on the manifold; several are grey safety clips that must be slid back before they release.", "Bag and label fasteners by step. There are many, and eight of them go into the manifold."], "steps": [{"n": 1, "title": "Top side: cover, intake, duct, fuel pressure", "caution": true, "blocks": [{"t": "text", "b": "Expansion-tank cap off. Engine cover off (clips). Airbox out (clamp at the turbo inlet, MAF unplugged, box lifts). Intake duct at the front: two T20s, cover off, two T25s, and the coolant line clipped to it."}, {"t": "text", "b": "Relieve fuel pressure: slowly loosen the 17mm high-pressure fitting at the high-pressure fuel pump with a rag around it, glasses on. Then pull the clamp back and remove the low-pressure fuel hose from the HPFP."}, {"t": "warn", "b": "The high-pressure side holds real pressure. Slow turn, rag, glasses. Fuel in your eyes ends the day."}]}, {"n": 2, "title": "Underneath: belly pan and the throttle-body side", "blocks": [{"t": "text", "b": "Car up, belly pan off (7× T25 and two clips). From below: unclip the harness, release the big coolant hose with a pick, unplug the MAP sensor behind it, remove the two T30s holding the throttle-body pipe (one hides behind the MAP), 7mm clamp and hose, then wiggle the whole hose assembly out."}]}, {"n": 3, "title": "Coolant pipe, throttle body, brackets", "blocks": [{"t": "text", "b": "Top side: coolant pipe off (2× T30 and a clamp); free the radiator hose below the throttle body with a pick and flat-band pliers (coolant comes out; pan ready). Throttle-body hose clamp (7mm). Manifold bracket: two 13mm up top and one M10 triple-square below, then free the harness from it. Throttle body: four aluminium T30s from behind and below with a mirror; hold it as the last one comes out."}, {"t": "warn", "b": "The throttle-body screws are aluminium. Socket fully seated, steady pressure. A stripped one is a drill-out on a $400 part."}]}, {"n": 4, "title": "Harness, bracket, oil filter housing, sensors", "blocks": [{"t": "text", "b": "Every connector and clip on the manifold: picks for the standard ones, slide the grey lock back on the safety clips first. Bracket under the wiring (2× T30) and its last connector. Oil filter housing off with the 32mm socket. Two more sensors on the manifold (one with a grey lock)."}]}, {"n": 5, "title": "Manifold off", "caution": true, "blocks": [{"t": "text", "b": "Manifold fasteners: 2× 10mm and 8× T30, out with a magnetic pickup in hand. HPFP: a captive T30 on the bracket in front, then the T30 holding the pump to the manifold. Lift the manifold up and away (disconnect the high-pressure line at the rail if it won't clear). Flip it and disconnect the vacuum assembly underneath."}, {"t": "ill", "id": "waterpump-mk7", "cap": "With the manifold off, the pump module is exposed on the front of the block with its belt cover."}, {"t": "warn", "b": "Open intake ports. Rag them now, before the next bolt."}]}, {"n": 6, "title": "Coolant lines, belt cover, belt", "blocks": [{"t": "text", "b": "Pull the clips on the upper and lower coolant lines outward with a pick and wiggle the lines off (pan underneath). Unclip the harness from the belt cover, two T30s (stubby), cover off. Slip the balance-shaft belt off the pump pulley."}]}, {"n": 7, "title": "Pump and thermostat module out", "blocks": [{"t": "text", "b": "Five captive T30s; the lower ones want the mirror and light. Wiggle the module off the block; there's one connector underneath with a safety tab to work free with a pick. Make sure the old thermostat gasket didn't stay on the block."}]}, {"n": 8, "title": "Build and fit the new module", "blocks": [{"t": "text", "b": "New thermostat housing onto the new pump on its dowels, five T30s. Connector on underneath. Module onto the block, five captive T30s snug in a criss-cross."}, {"t": "torque", "label": "Thermostat housing / pump module screws (T30)", "nm": 8, "c": {"level": "high", "n": 1, "note": "8 Nm (FCP Euro Mk7 GTI procedure)."}}, {"t": "text", "b": "Belt back on: 24mm socket on the crank, turn the engine slowly by hand while walking the belt onto the pump pulley. Belt cover (2× T30), harness clipped. Coolant lines clicked into their clips."}]}, {"n": 9, "title": "Everything back, to torque", "blocks": [{"t": "text", "b": "Vacuum assembly under the manifold, manifold on with a new gasket, HPFP T30 and its bracket, then the manifold fasteners."}, {"t": "torque", "label": "Intake manifold (2× 10mm, 8× T30)", "nm": 9, "c": {"level": "high", "n": 1, "note": "9 Nm (FCP)."}}, {"t": "torque", "label": "Manifold bracket: 13mm bolts · M10 triple-square", "nm": 10, "alt": [20], "c": {"level": "high", "n": 1, "note": "13mm bolts 10 Nm; the M10 triple-square below 20 Nm (FCP)."}, "note": "20 Nm for the M10 TS"}, {"t": "text", "b": "Sensors, brackets, harness with the safety clips locked, oil filter housing (32mm) to 2.5 Nm, throttle body."}, {"t": "torque", "label": "Throttle body screws (aluminium T30 ×4)", "nm": 7, "c": {"level": "high", "n": 1, "note": "7 Nm (FCP). Aluminium: not a Newton more."}}, {"t": "text", "b": "Throttle-body pipe from below (2× T30), MAP sensor, big coolant hose, harness, coolant pipe (2× T30), radiator hose, fuel hose with its clamp, high-pressure fitting snug, intake duct and coolant line, airbox, engine cover, belly pan."}]}, {"n": 10, "title": "Fill, bleed, check", "caution": true, "blocks": [{"t": "text", "b": "Vacuum-fill: tool on the expansion tank, pull vacuum (this also proves the system holds), open the valve to a bucket of 50/50 G13 and let it fill until the gauge reads zero. Without the tool: fill slowly, heater on hot, idle to temperature with the cap off, top up as the level drops."}, {"t": "warn", "b": "Check the fuel fitting at the HPFP for weeping before the first drive, with the engine idling and a light on it. Then check the coolant joints after the first full warm-up."}]}], "alsoReplace": [{"name": "PCV / air-oil separator", "why": "Top of the valve cover, four screws, and the airbox is already out. If it's original past 60k, now."}, {"name": "Intake valve carbon cleaning", "why": "The manifold is off and the ports are staring at you. On a 60–80k car this is the moment."}, {"name": "Spark plugs and coils", "why": "Coils are right there with the cover off; if they're due, do them."}, {"name": "Coolant line clips and the intake manifold gasket", "why": "Always, when disturbed."}], "check": {"tab": "Is it the pump?", "title": "Where is the coolant going?", "illId": "waterpump-mk7", "illCap": "The front of the block tells the story.", "rows": [{"see": "Crust or wetness on the front of the block under the manifold", "means": "Pump/housing module.", "do": "This guide."}, {"see": "Squeak at idle, pulley wobbles", "means": "Pump bearing.", "do": "This guide, soon."}, {"see": "Level dropping, no trace anywhere", "means": "Pressure-test first; could be the heater core or a hose end.", "do": "Pressure test before opening the manifold."}, {"see": "Gauge slow to warm, P0128", "means": "Thermostat.", "do": "Module (the thermostat's in it)."}], "c": {"level": "high", "n": 3, "note": "FCP symptoms; shop write-ups."}}, "aftercare": ["Coolant level after each of the first three drives.", "Look at the fuel fitting and the coolant joints at a week.", "Belly pan back on once it's proven dry."], "disagreements": [{"topic": "Plastic or aluminium housing?", "pos": "Aluminium fixes the warp; some report fit issues.", "call": "Either done right lasts. Latest-revision INA is the safe default; aluminium if you want it to be the last time."}, {"topic": "Book time", "pos": "5 hr book; owners 6 to a day.", "call": "Plan a day."}], "sources": ["FCP Euro 'How To Replace The Water Pump And Thermostat Housing On A MK7 Volkswagen GTI' (procedure, fasteners, torques)", "FCP Euro 'Definitive Guide To The Mk7 GTI EA888 Gen 3' (priority, symptoms)", "DAP 'MK7.5 GTI Water Pump Guide'", "NGP Gen 3 TSI maintenance guide; STR Gen 3 weaknesses (aluminium housings)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('pcv-mk7','cxca','pcv-mk7','PCV / air-oil separator replacement','Engine',null,array['pcv','air oil separator','screech','whistle','p0171','p0507']::text[],true,'45 min',1.5) on conflict (id) do update set guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('pcv-mk7',$j${"id": "pcv-mk7", "title": "PCV / air-oil separator replacement", "fits": "2015–2021 VW GTI (Mk7 / Mk7.5) · 2.0T TSI Gen 3", "heroId": "pcv-hero", "alsoFits": "EA888 Gen 3 MQB cars: Golf, Golf R, A3/S3 8V, Jetta/GLI, Tiguan (part revision by application)", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "45 min", "timeRepeat": "20 min", "difficulty": 1.5, "cost": "$120–200", "risk": "Small screws into aluminium · a torn diaphragm can already have pushed out the rear main seal", "why": "The Gen 3 kept the EA888's weak point: a rubber diaphragm in the air-oil separator bolted to the top of the engine. When it tears, the engine either pulls a vacuum leak (screech or whistle, lean codes, rough idle) or can't vent, and crankcase pressure looks for a way out, usually past the rear main seal. It's four screws on top of the engine; the consequences of ignoring it are not.", "note": "FCP lists it as high priority with an 8 Nm star-pattern torque; NGP and STR confirm the symptoms and the rear-main-seal risk."}, "heroCap": "On the Gen 3 the separator sits on top of the engine at the front of the cam cover with the breather hose to the turbo inlet. The drawing shows the same idea on the earlier engine; the part is different, the failure is the same.", "lifespan": {"title": "When to expect it", "headline": ["Commonly 60,000–100,000 miles; earlier on tuned cars"], "earliest": "40k on Stage 2 cars", "detail": "A screech or whistle from the engine bay at idle is the classic Gen 3 tell, along with P0171 (lean) or P0507 (idle high), rough idle, misfires, and sometimes smoke from the tailpipe. Oil at the bellhousing seam means the rear main seal has already been pushed out by crankcase pressure.", "factors": ["Tune (more crankcase pressure)", "Track use", "Age of the rubber"], "inspect": ["Screech or whistle at idle; oil-cap suction test; look at the bellhousing seam for oil"], "confidence": {"level": "high", "n": 4, "note": "FCP, NGP and STR agree on symptoms and consequences."}}, "should": {"yesIf": ["Screeching or whistling at idle", "P0171 or P0507", "Rough idle or misfires with no other cause", "Oil weep at the rear main seal (fix this first or the new seal blows too)"], "codes": ["P0171", "P0507", "P0300"], "notes": ["Part: the Gen 3 MQB separator (06K 103 495 family; revision by year and application). Buy by VIN. Kits include the gasket.", "Tuned or tracked cars: NGP's argument for the Gen 4 PCV retrofit or a catch can is that the stock diaphragm is marginal under sustained load. Stock daily cars: the latest OE part is fine.", "Check the rear main seal before you decide this is a small job. A weeping RMS means the separator failed a while ago and the seal is on the list too."], "confidence": {"level": "high", "n": 3, "note": "Part and torque from FCP; symptoms cross-confirmed."}}, "parts": [{"tier": "oe", "name": "Air-oil separator (PCV) with gasket", "pn": "06K 103 495 (revision by VIN)", "note": "", "price": "$120–200", "links": []}, {"tier": "oe", "name": "Breather hose if brittle", "pn": "—", "note": "", "price": "$30", "links": []}], "aftermarket": [{"name": "Gen 4 PCV retrofit (NGP and others)", "note": "The later engine's separator adapted to the Gen 3; a more robust diaphragm for tracked cars.", "price": "$200–300", "signal": "Track / tuned", "links": []}, {"name": "Catch can kits (034, IE, CTS)", "note": "Replace the separator function with an external can; the FSI catch can guide's reasoning applies.", "price": "$300–450", "signal": "Stage 2+", "links": []}], "tools": [{"name": "T30 Torx; hose-clamp pliers; small screwdriver for the hose clips"}, {"name": "Torque wrench reading 8 Nm"}], "before": ["Engine cool.", "Look at the bellhousing seam for oil before you start."], "steps": [{"n": 1, "title": "Cover off, hoses off", "blocks": [{"t": "text", "b": "Engine cover off (clips). The separator is the plastic unit on top at the front of the cam cover. Release the breather hose(s) at the separator (spring clips or quick-connects) and note their routing."}, {"t": "ill", "id": "pcv-hero", "cap": "Same failure, different engine: diaphragm unit on top, hose to the intake side."}]}, {"n": 2, "title": "Separator off", "blocks": [{"t": "text", "b": "Remove the T30 screws holding the separator (count them; typically four or five), lift it off, and clean the cam cover face. Keep anything from falling in the openings."}]}, {"n": 3, "title": "New separator on", "blocks": [{"t": "text", "b": "New gasket seated, separator down, screws snug in a star pattern starting with the one nearest the PCV hose."}, {"t": "torque", "label": "Air-oil separator screws (T30)", "nm": 8, "c": {"level": "high", "n": 1, "note": "8 Nm in a star pattern from the bolt nearest the PCV hose (FCP Gen 3 torque list)."}}]}, {"n": 4, "title": "Hoses, cover, listen", "blocks": [{"t": "text", "b": "Hoses back on until they click. Cover on. Start it: the screech should be gone and the idle steady within a minute. Oil-cap test: gentle suction only."}]}], "alsoReplace": [{"name": "Rear main seal check", "why": "Oil at the bellhousing seam means it's already gone; fix the PCV first, then the seal."}, {"name": "Breather hose", "why": "Brittle plastic; if a clip cracks, replace the hose."}], "check": {"tab": "Is it the PCV?", "title": "Is it the separator?", "illId": "pcv-hero", "illCap": "Screech plus suction settles it.", "rows": [{"see": "Screech/whistle at idle, hard suction at the oil cap", "means": "Torn diaphragm, stuck open.", "do": "Replace."}, {"see": "Oil at the bellhousing, oil consumption", "means": "Stuck closed; pressure pushed the RMS.", "do": "Replace, then the seal."}, {"see": "Lean codes, no noise", "means": "PCV, intake leak or a boost hose.", "do": "Oil-cap test; then hoses."}], "c": {"level": "high", "n": 3, "note": "FCP/NGP/STR."}}, "aftercare": ["Watch the bellhousing seam for a month if the failure was old."], "disagreements": [{"topic": "OE or catch can?", "pos": "Forums push catch cans; FCP keeps it OE.", "call": "OE on a stock daily. Catch can or Gen 4 retrofit on a tuned/tracked car."}], "sources": ["FCP Euro Gen 3 engine guide (priority, torque, symptoms) and PCV replacement DIY", "NGP Racing Gen 3 TSI maintenance guide (symptoms, Gen 4 retrofit)", "STR Performance Gen 3 weaknesses"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('plugs-mk7','cxca','plugs-mk7','Spark plugs & coil packs','Engine',null,array['spark plug','coils','coil pack','misfire']::text[],true,'45 min',1.5) on conflict (id) do update set guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('plugs-mk7',$j${"id": "plugs-mk7", "title": "Spark plugs & coil packs", "fits": "2015–2021 VW GTI (Mk7 / Mk7.5) · 2.0T TSI Gen 3", "heroId": "ignition-hero", "alsoFits": "EA888 Gen 3 2.0T: Golf R, A3/S3, GLI, Tiguan (same plugs; coil revision by year)", "category": "Engine", "kind": "repair", "variants": {"question": "Stock or tuned?", "hint": "Tuned Gen 3s run more cylinder pressure and want a colder plug with a slightly smaller gap.", "options": [{"id": "stock", "label": "Stock or Stage 1", "when": "Factory-spec plug at the factory gap"}, {"id": "tuned", "label": "Stage 2, IS38 or bigger", "when": "One range colder, gapped tighter per your tuner"}]}, "glance": {"timeFirst": "45 min", "timeRepeat": "20 min", "difficulty": 1.5, "cost": "$40–60 plugs · $60–120 coils", "risk": "Cross-threading a plug · dropping debris in the plug well", "why": "Plugs wear and coils die, and on a turbo engine both show up as a misfire under boost first. FCP says check the plugs at 40k and every 20k after; updated coils are the other low-priority Gen 3 item. Coils pull straight out; there are no bolts.", "note": "FCP's Gen 3 guide sets the interval; plug and coil specifics from Mk7 parts listings, flagged where a factory figure wasn't confirmed."}, "heroCap": "Coil packs sit in the plug wells on top of the valve cover, one per cylinder, held by friction. Unplug, pull straight up, and the plug is below on a 5/8\" (16mm) socket.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Plugs: check at 40,000 miles, then every 20,000; replace as needed", "only": ["stock"]}, {"text": "Plugs: 20,000–30,000 miles on a tuned car", "only": ["tuned"]}], "earliest": "Copper race plugs (BKR7E) need changing every 12,000–15,000", "detail": "A tired plug misfires under load first. A dying coil is the same symptom on one cylinder with a code that names it. VW revised the Gen 3 coil more than once; buy the latest revision and replace as a set.", "factors": ["Tune", "Oil in the plug wells from a leaking valve cover gasket (kills coils)", "Wrong gap for the boost level"], "inspect": ["Any misfire code: pull the coil on that cylinder and swap it with a neighbour. If the code follows the coil, it's the coil."], "confidence": {"level": "community", "n": 4, "note": "Owner practice and vendor kit notes; the factory table wasn't fetched this pass."}}, "should": {"yesIf": ["Misfire under boost, worse when it's cold and damp", "Misfire code on a specific cylinder (P0301–P0304)", "40k since the last plugs, or unknown", "Just tuned it and still on stock plugs"], "codes": ["P0300", "P0301", "P0302", "P0303", "P0304"], "notes": ["Plug: the factory part is 06K 905 601 B (an NGK-made unit). Colder options for tuned cars are the usual NGK one-range-colder equivalents; your tuner's recommendation wins. Buy by VIN and don't re-gap iridium tips with a tool.", {"text": "Gap: leave the pre-gapped factory setting; check with a wire gauge only.", "only": ["stock"]}, {"text": "Gap: tuners typically call for a tighter gap on Stage 2 and IS38 cars to stop spark blow-out under boost. Use your tune's number.", "only": ["tuned"]}, "Coils: latest-revision Gen 3 coils (06K 905 110 family) as a set of four. Red 'R8' coils fit and are the same idea as on the Mk5; no performance change."], "confidence": {"level": "high", "n": 4, "note": "Plug families, gaps and coil equivalence agree across a parts specialist's listing and multiple forum threads."}}, "parts": [{"tier": "oe", "name": "Spark plugs (×4), factory", "pn": "06K 905 601 B", "note": "Pre-gapped", "price": "$40–60", "links": [], "only": ["stock"]}, {"tier": "aftermarket", "name": "Spark plugs (×4), one range colder", "pn": "per tuner", "note": "Gap per tune", "price": "$40–60", "links": [], "only": ["tuned"]}, {"tier": "oe", "name": "Ignition coils (×4), latest revision", "pn": "06K 905 110 (revision by VIN)", "note": "Set", "price": "$120–200", "links": []}, {"tier": "oe", "name": "Dielectric grease", "pn": "—", "note": "", "price": "$8", "links": []}], "aftermarket": [{"name": "Updated Gen 3 coil kit (FCP kit)", "note": "Latest-revision coils in a set; FCP reviewed it as the fix for Gen 3 coil misfires.", "price": "$150–200", "signal": "Updated coils", "links": []}, {"name": "Red 'R8' coils", "note": "Fit, look good, same job.", "price": "$80–120", "signal": "Cosmetic", "links": []}], "tools": [{"name": "5/8\" (16mm) thin-wall plug socket, extension, 3/8\" ratchet"}, {"name": "Torque wrench to 30 Nm; wire gap gauge; small screwdriver for connector locks"}], "before": ["Engine cold.", "Blow or vacuum the wells before the plugs come out.", "One cylinder at a time."], "steps": [{"n": 1, "title": "Cover off, unplug the coils", "blocks": [{"t": "text", "b": "Engine cover off (air filter guide). Four coils in a row on the valve cover. Press or lift each connector's lock tab with a small screwdriver and unplug it."}]}, {"n": 2, "title": "Pull the coils", "blocks": [{"t": "text", "b": "Grip the coil by its body and pull straight up; they're a friction fit and can be stubborn. A coil puller tool helps; a wide screwdriver under the coil's lip, gently, is the owner method. Look at each one: cracks in the boot or oil on it mean the coil is dead or the cover gasket is leaking."}, {"t": "ill", "id": "ignition-hero", "cap": "Coil on top, plug below; unplug, pull straight up, plug out on a 5/8\" socket. Same on the Gen 3."}]}, {"n": 3, "title": "Plugs out", "blocks": [{"t": "text", "b": "Blow the wells clear. 5/8\" plug socket on an extension, break each plug loose and spin it out. Read them as they come out (see the table below); a plug that's oily or white tells you something."}]}, {"n": 4, "title": "Gap and fit the new plugs", "caution": true, "blocks": [{"t": "text", "b": "Check the gap with a wire gauge without touching the centre electrode; leave the factory setting for a stock or Stage 1 car.", "only": ["stock"]}, {"t": "text", "b": "Set the gap to your tune's figure with a wire gauge, bending only the ground strap.", "only": ["tuned"]}, {"t": "text", "b": "Thread each plug in by hand, using the socket without the ratchet, until it seats. If it resists before seating, back out and restart; never force it. Then torque."}, {"t": "torque", "label": "Spark plugs (flat seat with gasket)", "nm": 25, "alt": [30], "c": {"level": "varies", "n": 2, "note": "25–30 Nm; no factory figure confirmed for the Gen 3 this pass. Hand-start plus a firm quarter turn lands here."}}, {"t": "warn", "b": "Cross-threading a plug in an aluminium head is the one way this job goes badly. Hand start, every time."}]}, {"n": 5, "title": "Coils in, plugs in the connectors", "blocks": [{"t": "text", "b": "Dab of dielectric grease inside each coil boot. Push each coil down until it seats over the plug with a definite stop. Connectors on until they click. Cover on."}]}, {"n": 6, "title": "Start and drive", "blocks": [{"t": "text", "b": "Idle should be smooth immediately. Drive it and give it full throttle in a middle gear once warm; a stumble that's gone is the point. A stumble that remains with new plugs and coils is not ignition: think PCV, diverter valve, or fuel."}]}], "alsoReplace": [{"name": "Valve cover gasket", "why": "Oil in the plug wells kills coils. If the wells are wet, the gasket is the cause and it's a one-hour job."}, {"name": "PCV valve", "why": "Rough idle blamed on plugs is often the PCV. Same access."}], "check": {"tab": "Read the plugs", "title": "Reading the old plugs", "illId": "ignition-hero", "illCap": "Tan is right. Everything else is a clue.", "rows": [{"see": "Light tan to grey electrode, no deposits", "means": "Healthy engine, plug simply aged.", "do": "Replace, same type."}, {"see": "Black, sooty and dry", "means": "Rich, or the plug is too cold for the car, or lots of idling.", "do": "Check gap and heat range; if you fitted BKR8s on a Stage 1, that's why."}, {"see": "Oily, wet", "means": "Oil in the well from the cover gasket, or oil past the rings/PCV.", "do": "Gasket first; new coil on that cylinder."}, {"see": "White, blistered, tiny beads on the electrode", "means": "Too hot: lean, too much boost, or the plug is too hot a range.", "do": "Colder plug and a look at the tune before you damage a piston."}], "c": {"level": "community", "n": 3, "note": "Standard plug reading; consistent with forum experience on this engine."}}, "aftercare": ["Note mileage and plug type in the glovebox.", "Misfire returns on one cylinder: swap coils between cylinders and see if it moves."], "disagreements": [{"topic": "Plug torque", "pos": "25 vs 30 Nm.", "call": "25–30, flagged."}, {"topic": "Interval", "pos": "VW: check at 40k. Owners: replace at 40k.", "call": "Check at 40k and replace if they look tired; tuned cars replace at 20–30k."}], "sources": ["FCP Euro Gen 3 engine guide (intervals, coil priority)", "FCP Euro Mk7 ignition coil kit review", "Mk7 GTI plug and coil listings (06K 905 601 B, 06K 905 110)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('air-filter-mk7','cxca','air-filter-mk7','Engine air filter','Engine','air intake',array['air filter','airbox']::text[],true,'10 min',1) on conflict (id) do update set guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('air-filter-mk7',$j${"id": "air-filter-mk7", "title": "Engine air filter", "fits": "2015–2021 VW GTI (Mk7 / Mk7.5) · 2.0T TSI Gen 3", "alsoFits": "MQB 1.8T/2.0T Golf, GTI, Golf R, A3/S3 (same airbox family)", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "10 min", "timeRepeat": "10 min", "difficulty": 1, "cost": "$15–30", "risk": "None worth mentioning", "why": "The Mk7 airbox sits on top of the engine at the front with a lid on a handful of screws and the MAF in its outlet. FCP says check it yearly; the ten-minute version of maintenance.", "note": "MQB airbox; fastener count varies slightly by year, so count yours."}, "heroCap": "MQB airbox at the front-left with a screwed lid and the MAF in the outlet tube; the drawing shows the same layout on the earlier TSI.", "lifespan": {"title": "When to expect it", "headline": ["Inspect yearly; owners replace around every 20,000–40,000 miles"], "earliest": null, "detail": "A paper filter fails gradually. Hold it up to the light: if you can't see light through the pleats, or there's grit and leaves in the airbox, change it. Dusty roads and a lot of highway bugs shorten it.", "factors": ["Dusty or gravel roads", "Unknown history", "Rodent activity in the engine bay (check the snorkel)"], "inspect": ["Every oil change: pull the cover and look. It's two screws."], "confidence": {"level": "single", "n": 1, "note": "Factory interval not confirmed in this pass. Owner practice and vendor advice only."}}, "should": {"yesIf": ["You don't know when it was last done", "Filter looks grey, or you can't see light through it", "Debris in the airbox", "Every year or so regardless"], "codes": [], "notes": ["Stock paper filter versus an oiled cotton cone: the forums are clear that the stock box pulls cool air from the grille and the paper element isn't a restriction on a stock or Stage 1 car. Oiled filters can also foul the mass-airflow sensor. Stay paper unless you're going to a full intake (that's a separate guide)."], "confidence": {"level": "high", "n": 3, "note": "Vendor write-ups and forum consensus agree."}}, "parts": [{"tier": "oe", "name": "Engine air filter, Genuine VW", "pn": "5Q0 129 620 B (confirm by VIN)", "note": "", "price": "$20–35", "links": []}, {"tier": "oem", "name": "Mann / Mahle equivalent", "pn": "by application", "note": "", "price": "$15–25", "links": []}], "aftermarket": [{"name": "Drop-in cotton panel (K&N, aFe)", "note": "Fits the stock box. Slight airflow gain on paper, real risk of oil on the MAF sensor if over-oiled, and no cold-air benefit. Forums are lukewarm.", "price": "$50–70", "signal": "Community verdict: stay paper", "links": []}], "tools": [{"name": "T25 Torx (some years T20); pliers for the breather tube"}], "before": ["Engine off and cool enough to lean over.", "Have the new filter out of the box so you can compare it to the old one."], "steps": [{"n": 1, "title": "Find the box", "blocks": [{"t": "text", "b": "Front-left of the bay on top of the engine: the airbox lid with screws around it and the MAF in the outlet tube toward the turbo."}, {"t": "ill", "id": "airbox-tsi", "cap": "Same idea as the earlier TSI: lid off, filter out."}]}, {"n": 2, "title": "Lid screws, hose, lid off", "blocks": [{"t": "text", "b": "Loosen the lid screws (captive on most years; count them). Unclip the small breather hose at the lid if fitted. Lift the lid; the MAF and outlet stay attached to it, so just tip it aside."}]}, {"n": 3, "title": "Filter out, box clean, new filter in", "blocks": [{"t": "text", "b": "Lift the panel filter, vacuum the box, new filter with its rubber edge seated all round. Lid on, screws snug (plastic), breather hose back."}]}], "alsoReplace": [{"name": "Cabin air filter", "why": "Same trip to the parts store, same 'nobody ever changed it' energy. It's behind the glovebox and takes ten minutes."}], "check": {"tab": "Read the filter", "title": "Reading your old filter", "illId": "airbox", "illCap": "Light through the pleats is the test.", "rows": [{"see": "Off-white, light passes through easily", "means": "Fine.", "do": "Put it back or replace if it's cheap and you're already here."}, {"see": "Grey, light passes with effort", "means": "Doing its job; near the end.", "do": "Replace."}, {"see": "Black, blocked, or debris/rodent nesting in the box", "means": "Restricting airflow; the previous owner never did this.", "do": "Replace, vacuum the box, check the snorkel and inlet pipe for debris."}], "c": {"level": "community", "n": 3, "note": "Standard practice; consistent across sources."}}, "aftercare": ["Note the mileage somewhere you'll find it.", "If you ever see oil residue on the MAF sensor after switching to an oiled filter, clean it with MAF cleaner and go back to paper."], "disagreements": [{"topic": "Interval", "pos": "FCP says 30–40k; owners inspect yearly.", "call": "Inspect at every oil change; replace when it fails the light test."}], "sources": ["FCP Euro Gen 3 engine guide (interval)", "MQB airbox listings and owner videos"], "embeds": [], "heroId": "airbox-tsi"}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
